// テキスト中の同義語をすべて「グループの先頭表記」に置換してから比較する
function expandSyn(text) {
  let out = normJa(text);
  for (const group of INGREDIENT_SYNONYMS) {
    const canon = normJa(group[0]);
    for (const variant of group) {
      const nv = normJa(variant);
      if (nv && nv !== canon && out.includes(nv)) out = out.split(nv).join(canon);
    }
  }
  return out;
}
function matchFood(food, q) {
  const nq = expandSyn(q);
  return expandSyn(food.n).includes(nq) || expandSyn(food.c).includes(nq) || expandSyn(food.kana || "").includes(nq);
}

// モードに応じた判定を返す (mode: "reboot" | "paleo")
function verdictFor(food, mode) {
  if (mode === "paleo" && food.p) return food.p;
  return food.v;
}
function reasonFor(food, mode) {
  if (mode === "paleo" && food.pr) return food.pr;
  return food.r;
}
// モード別のカウンター上限
const MODE_LIMITS = {
  reboot: { fruit: 100, coffee: 200, tea: 500 },
  paleo:  { fruit: 300, coffee: 400, tea: 1000 },
};

