const KEY = "reboot30:state";
const MYRECIPES_KEY = "reboot30:myrecipes";
const FOLDERS_KEY = "reboot30:folders";
const MAX_FOLDERS = 10;
const todayStr = (d = new Date()) => {
  const x = new Date(d); x.setHours(0,0,0,0);
  return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,"0")}-${String(x.getDate()).padStart(2,"0")}`;
};
// "YYYY-MM-DD" 形式の日付キー文字列を必ずローカルタイムの深夜0時として解釈するヘルパー。
// new Date("YYYY-MM-DD") はUTCとして解釈される仕様のため、UTC以外のタイムゾーンでは
// 1日前にズレるバグの原因になる。日付キー文字列から Date を作るときは必ずこちらを使う。
const parseLocalDate = (ds) => {
  const [y, m, d] = ds.split("-").map(Number);
  return new Date(y, m - 1, d);
};
const daysBetween = (a, b) => Math.round((parseLocalDate(b) - parseLocalDate(a)) / 86400000);
// 日付に対してn日を安全に加算する(setDateを使うことで夏時間の切り替わりでも1日ズレない)
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };

const loadState = async () => {
  try { const r = localStorage.getItem(KEY); return r ? JSON.parse(r) : null; }
  catch { return null; }
};
const saveState = async (s) => {
  try { localStorage.setItem(KEY, JSON.stringify(s)); } catch (e) { console.error(e); }
};
