/* ============================================================
   MAIN APP
   ============================================================ */
const SPLASH_BG = "data:image/jpeg;base64,";
const SPLASH_FIG1 = "data:image/png;base64,";
const SPLASH_FIG2 = "data:image/png;base64,";
const SPLASH_FIG3 = "data:image/png;base64,";
const SPLASH_FIG4 = "data:image/png;base64,";
const SPLASH_FIG5 = "data:image/png;base64,";
const SPLASH_FIG6 = "data:image/png;base64,";
// 6人物のスケール・立ち位置(元画像の足元座標から算出した「傾斜を上る」オフセット)
// 6人物: 背景画像上の位置(x%, 足元y%)と高さ(%, 背景全体高さに対する比率)。
// 背景の斜めの下線に沿うよう実測値から算出。
// 6人物: 背景画像上の位置(x%, 足元y%)と高さ(%, 背景全体高さに対する比率)。
// 「ORIGINAL」の文字ブロック(実測 y=51.7%〜70.5%)と重ならないよう、十分な余白を取って上に配置。
// 6人物: 完成見本(963E0CED...png)から実測した位置(x中心%, 足元y%, 高さ%)。
// 文字「ORIGINAL」のすぐ上に密着し、左下→右上へ斜めに並ぶ配置。
const SPLASH_FIGURES = [
  { src: SPLASH_FIG1, x: 15.2, y: 56.8, h: 17.8 },
  { src: SPLASH_FIG2, x: 29.1, y: 55.3, h: 18.3 },
  { src: SPLASH_FIG3, x: 42.1, y: 53.9, h: 18.4 },
  { src: SPLASH_FIG4, x: 55.6, y: 52.0, h: 17.8 },
  { src: SPLASH_FIG5, x: 67.5, y: 51.3, h: 18.3 },
  { src: SPLASH_FIG6, x: 82.0, y: 50.0, h: 18.6 },
];
function Splash({ leaving }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "#EBF0DF", zIndex: 999,
      opacity: leaving ? 0 : 1, transition: "opacity 1.6s ease-in-out", overflow: "hidden" }}>
      {/* 背景と人物を同じ座標系(941:1672比率)で重ねるための枠 */}
      <div style={{ position: "absolute", inset: 0, maxWidth: 480, margin: "0 auto", overflow: "hidden" }}>
        {/* 背景(葉っぱ・アーチ・ORIGINALロゴ・キャッチコピー・斜めの下線) */}
        <img src={SPLASH_BG} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%",
          objectFit: "cover", animation: "splashBgIn 0.9s ease-out forwards", opacity: 0 }} />
        {/* 6人物: 太った人→旧石器時代の人へ左下から右上に、拡大や弾みを使わずゆっくり溶けるように出現 */}
        {SPLASH_FIGURES.map((f, i) => (
          <img key={i} src={f.src} alt="" style={{
            position: "absolute", left: `${f.x}%`, top: `${f.y}%`, height: `${f.h}%`,
            "--tx": "-50%", "--ty": "-100%",
            opacity: 0,
            animation: "splashFigIn 1.2s ease-out forwards",
            animationDelay: `${0.15 + i * 0.32}s`,
          }} />
        ))}
      </div>
      <style>{`
        @keyframes splashBgIn { 0% { opacity: 0; } 100% { opacity: 1; } }
        @keyframes splashFigIn {
          0%   { opacity: 0; transform: translate(var(--tx), var(--ty)) translateY(8px); filter: blur(7px); }
          100% { opacity: 1; transform: translate(var(--tx), var(--ty)) translateY(0);    filter: blur(0px); }
        }
      `}</style>
    </div>
  );
}

export default function App() {
  const [state, setState] = useState(null);
  const [myRecipes, setMyRecipes] = useState([]);
  const [folders, setFolders] = useState([]);
  const [tab, setTab] = useState("home");
  const [loaded, setLoaded] = useState(false);
  const [showSplash, setShowSplash] = useState(true);
  const [splashLeaving, setSplashLeaving] = useState(false);
  const [editDate, setEditDate] = useState(todayStr());

  useEffect(() => {
    // 背景フェードイン(0.9s)+6人物が拡大なしでゆっくり溶けるように出現(約3s)→ 1秒静止 → 1.6秒かけてゆっくり消える
    const t1 = setTimeout(() => setSplashLeaving(true), 4000);
    const t2 = setTimeout(() => setShowSplash(false), 5600);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  useEffect(() => {
    (async () => {
      const s = await loadState();
      // アプリは常に「パレオ(標準モード)」で開く。リブートへの切替はセッション中のみ有効
      setState(s
        ? { ...s, settings: { ...s.settings, mode: "paleo" } }
        : { settings: { startDate: todayStr(), mode: "paleo" }, days: {} });
      const mr = await loadMyRecipes();
      setMyRecipes(mr);
      const fl = await loadFolders();
      setFolders(fl);
      setLoaded(true);
    })();
  }, []);

  useEffect(() => { if (loaded && state) saveState(state); }, [state, loaded]);
  useEffect(() => { if (loaded) saveMyRecipes(myRecipes); }, [myRecipes, loaded]);
  useEffect(() => { if (loaded) saveFolders(folders); }, [folders, loaded]);

  // タブを切り替えたら必ずページ先頭で開く(前のページのスクロール位置を引き継がない)
  useEffect(() => {
    window.scrollTo(0, 0);
    document.documentElement.scrollTop = 0;
    document.body.scrollTop = 0;
  }, [tab]);

  if (showSplash) return <Splash leaving={splashLeaving} />;

  if (!loaded || !state) {
    return <div style={{ height: "100vh", display: "grid", placeItems: "center", background: C.paper, fontFamily: FONT, color: C.inkSoft }}>読み込み中…</div>;
  }

  const start = state.settings.startDate;
  const today = todayStr();
  const currentDay = Math.min(30, daysBetween(start, today) + 1);
  const mode = state.settings.mode || "paleo";
  const setMode = (m) => setState((prev) => ({ ...prev, settings: { ...prev.settings, mode: m } }));
  const getDay = (ds) => state.days[ds] || null;
  const setDay = (ds, updater) => {
    setState((prev) => {
      const cur = prev.days[ds] ? JSON.parse(JSON.stringify(prev.days[ds])) : emptyDay();
      const next = typeof updater === "function" ? updater(cur) : updater;
      return { ...prev, days: { ...prev.days, [ds]: next } };
    });
  };

  const resetToDay1 = () => {
    setState((prev) => ({
      ...prev,
      settings: { ...prev.settings, startDate: todayStr(), lastReset: todayStr() },
      days: { ...prev.days, [todayStr()]: { ...(prev.days[todayStr()] || emptyDay()), violation: true } },
    }));
  };

  const addMyRecipe = (r) => setMyRecipes((prev) => [...prev, r]);
  const deleteMyRecipe = (id) => setMyRecipes((prev) => prev.filter((r) => r.id !== id));
  const addFolder = (name) => {
    if (folders.length >= MAX_FOLDERS) return false;
    const n = (name || "").trim();
    if (!n) return false;
    setFolders((prev) => [...prev, { id: "f" + Date.now(), name: n }]);
    return true;
  };
  const renameFolder = (id, name) => setFolders((prev) => prev.map(f => f.id === id ? { ...f, name: (name||"").trim() || f.name } : f));
  const deleteFolder = (id) => {
    setFolders((prev) => prev.filter(f => f.id !== id));
    // 削除されたフォルダのレシピは「未分類(マイレシピ直下)」に戻す
    setMyRecipes((prev) => prev.map(r => r.folderId === id ? { ...r, folderId: null } : r));
  };
  const moveRecipeToFolder = (recipeId, folderId) =>
    setMyRecipes((prev) => prev.map(r => r.id === recipeId ? { ...r, folderId: folderId || null } : r));

  const shared = { state, setState, currentDay, start, today, getDay, setDay, resetToDay1, setTab,
    myRecipes, addMyRecipe, deleteMyRecipe, mode, setMode, th: THEME(mode),
    editDate, setEditDate,
    folders, addFolder, renameFolder, deleteFolder, moveRecipeToFolder };

  const TABS = [
    { id: "home", label: "ホーム", Icon: Home },
    { id: "log", label: "記録", Icon: ClipboardList },
    { id: "recipes", label: "レシピ", Icon: ChefHat },
    { id: "check", label: "判定", Icon: Search },
    { id: "calendar", label: "カレンダー", Icon: CalendarDays },
  ];

  const th = THEME(mode);
  return (
    <div style={{ fontFamily: FONT, backgroundColor: th.paper, color: C.ink, minHeight: "100vh",
      maxWidth: 480, margin: "0 auto", position: "relative", paddingBottom: 76, transition: "background-color .3s" }}>
      {tab === "home" && <HomeScreen {...shared} />}
      {tab === "log" && <LogScreen {...shared} />}
      {tab === "recipes" && <RecipesScreen {...shared} />}
      {tab === "check" && <CheckScreen {...shared} />}
      {tab === "calendar" && <CalendarScreen {...shared} />}

      <nav style={{ position: "fixed", bottom: 0, left: 0, right: 0, maxWidth: 480, margin: "0 auto",
        background: C.card, borderTop: `1px solid ${C.line}`, display: "flex",
        padding: "8px 4px calc(8px + env(safe-area-inset-bottom))", zIndex: 40 }}>
        {TABS.map(({ id, label, Icon }) => {
          const on = tab === id;
          return (
            <button key={id} onClick={() => setTab(id)} style={{
              flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 3,
              background: "none", border: "none", cursor: "pointer", color: on ? th.accent : C.inkFaint, fontFamily: FONT }}>
              <Icon size={22} strokeWidth={on ? 2.6 : 2} />
              <span style={{ fontSize: 10.5, fontWeight: on ? 700 : 500 }}>{label}</span>
            </button>
          );
        })}
      </nav>
    </div>
  );
}

// モード別テーマ(全体の色合い)

function THEME(mode) {
  return mode === "paleo"
    ? {
        paper: "#FBF0E0", accent: "#C9772C", accentDeep: "#9E5518", accentSoft: "#F6E6D2", tag: "パレオ",
        bannerFrom: "#9E5518", bannerTo: "#D98A3A",
      }
    : {
        paper: "#EEF3E4", accent: C.green, accentDeep: C.greenDeep, accentSoft: C.greenSoft, tag: "リブート",
        bannerFrom: "#3E5E24", bannerTo: "#6B9A44",
      };
}

/* ============================================================
   HOME
   ============================================================ */
function HomeScreen({ state, currentDay, today, getDay, start, setTab, mode, setMode, th }) {
  const day = getDay(today);
  const { score, rank, parts } = scoreDay(day || emptyDay(), mode);
  const [guideOpen, setGuideOpen] = useState(false);
  const [scoreOpen, setScoreOpen] = useState(false);

  let completed = 0;
  for (let i = 0; i < currentDay; i++) {
    const ds = todayStr(addDays(parseLocalDate(start), i));
    const d = state.days[ds];
    if (d && d.violation) { completed = 0; } else { completed++; }
  }

  const watch = useMemo(() => nutritionWatch(state, today), [state, today]);
  const isDone = currentDay >= 30;
  const pct = Math.min(100, score);
  const ringColor = RANK_COLOR[rank] || C.green;

  return (
    <div>
      <Header th={th} title={mode === "paleo" ? "パレオ生活" : "30日リブート"} sub={`${new Date().getMonth()+1}月${new Date().getDate()}日`} />
      <div style={{ padding: "4px 18px 18px" }}>

        <ModeToggle mode={mode} setMode={setMode} th={th} />

        <div style={{ background: C.card, borderRadius: 22, padding: 20, border: `1px solid ${C.line}`,
          display: "flex", alignItems: "center", gap: 20, boxShadow: "0 2px 10px rgba(90,80,50,0.04)" }}>
          <button onClick={()=>setScoreOpen(true)} style={{ position: "relative", width: 112, height: 112, flexShrink: 0,
            background: "none", border: "none", padding: 0, cursor: "pointer", fontFamily: FONT }}>
            <svg width="112" height="112" viewBox="0 0 112 112">
              <circle cx="56" cy="56" r="48" fill="none" stroke={C.cardWarm} strokeWidth="10" />
              <circle cx="56" cy="56" r="48" fill="none" stroke={ringColor} strokeWidth="10"
                strokeLinecap="round" strokeDasharray={`${(pct/100)*301.6} 301.6`}
                transform="rotate(-90 56 56)" style={{ transition: "stroke-dasharray .5s" }} />
            </svg>
            <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", textAlign: "center" }}>
              <div>
                <div style={{ fontSize: 30, fontWeight: 800, color: ringColor, lineHeight: 1 }}>{rank}</div>
                <div style={{ fontSize: 12, color: C.inkSoft, marginTop: 2, textDecoration: "underline", textDecorationColor: C.line }}>{score}点</div>
              </div>
            </div>
          </button>
          <div>
            <div style={{ fontSize: 13, color: th.accent, fontWeight: 700 }}>{mode === "paleo" ? "パレオ生活" : (isDone ? "🎉 30日達成！" : "リブート")}</div>
            <div style={{ fontSize: 40, fontWeight: 800, color: th.accentDeep, lineHeight: 1.1 }}>
              Day {currentDay}{mode !== "paleo" && <span style={{ fontSize: 18, color: C.inkFaint }}> / 30</span>}
            </div>
            <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 4 }}>連続 {completed} 日クリア</div>
            <button onClick={()=>setScoreOpen(true)} style={{ marginTop: 8, background: "none", border: "none",
              padding: 0, cursor: "pointer", fontFamily: FONT, fontSize: 12, fontWeight: 700, color: th.accent,
              display: "flex", alignItems: "center", gap: 4 }}>
              {score}点の内訳をみる <ChevronRight size={13} />
            </button>
          </div>
        </div>

        {mode !== "paleo" && (
          <div style={{ height: 8, background: C.cardWarm, borderRadius: 999, marginTop: 14, overflow: "hidden" }}>
            <div style={{ height: "100%", width: `${(currentDay/30)*100}%`, background: th.accent, borderRadius: 999 }} />
          </div>
        )}

        <button onClick={()=>setGuideOpen(true)} style={{ width: "100%", marginTop: 14, background: C.card,
          border: `1.5px solid ${C.line}`, borderRadius: 16, padding: "13px 16px", display: "flex",
          alignItems: "center", gap: 10, cursor: "pointer", fontFamily: FONT }}>
          <span style={{ width: 36, height: 36, borderRadius: 10, background: th.accentSoft, display: "grid", placeItems: "center", flexShrink: 0 }}>
            <BookOpen size={18} color={th.accentDeep} /></span>
          <span style={{ textAlign: "left" }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: C.ink }}>プログラムガイド</div>
            <div style={{ fontSize: 11.5, color: C.inkFaint }}>リブートとパレオの違い・原則・注意点</div>
          </span>
        </button>

        {isDone && mode !== "paleo" && <CompletionCard state={state} start={start} />}

        <SectionLabel>栄養ウォッチ</SectionLabel>
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {watch.map((w, i) => (
            <div key={i} style={{ background: w.ok ? C.greenSoft : C.carrotSoft, borderRadius: 14,
              padding: "12px 14px", display: "flex", gap: 10, alignItems: "flex-start" }}>
              <Heart size={17} color={w.ok ? C.green : C.carrot} style={{ flexShrink: 0, marginTop: 1 }} />
              <div>
                <div style={{ fontSize: 13.5, fontWeight: 700, color: w.ok ? C.greenDeep : C.carrot }}>{w.title}</div>
                <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 2, lineHeight: 1.5 }}>{w.msg}</div>
              </div>
            </div>
          ))}
        </div>

        <div style={{ height: 8 }} />
      </div>
      {guideOpen && <GuideScreen onClose={() => setGuideOpen(false)} mode={mode} th={th} />}
      {scoreOpen && (
        <Modal onClose={()=>setScoreOpen(false)} title={`今日のスコア ${score}点 (${rank})`}>
          <div style={{ fontSize: 12.5, color: C.inkSoft, marginBottom: 12, lineHeight: 1.6 }}>
            達成した項目が加点されます。NG食品を避けるのは前提条件です。
          </div>
          <div style={{ background: C.card, borderRadius: 16, border: `1px solid ${C.line}`, overflow: "hidden" }}>
            {parts.map((p, i) => (
              <div key={i} style={{ display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "12px 14px", borderTop: i ? `1px solid ${C.line}` : "none" }}>
                <span style={{ display: "flex", alignItems: "center", gap: 9, fontSize: 14,
                  color: p.ok ? C.ink : C.inkFaint }}>
                  <span style={{ width: 22, height: 22, borderRadius: 999, display: "grid", placeItems: "center",
                    background: p.ok ? th.accentSoft : C.cardWarm }}>
                    {p.ok ? <Check size={14} strokeWidth={3} color={th.accent} /> : <span style={{ width: 6, height: 6, borderRadius: 999, background: C.inkFaint }} />}
                  </span>
                  {p.label}
                </span>
                <span style={{ fontSize: 13.5, fontWeight: 800, color: p.ok ? th.accent : C.inkFaint }}>
                  {p.ok ? `+${p.pts}` : `+0`}
                </span>
              </div>
            ))}
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 14,
            padding: "0 4px", fontSize: 15, fontWeight: 800 }}>
            <span>合計</span><span style={{ color: th.accentDeep }}>{score} / 100点</span>
          </div>
        </Modal>
      )}
    </div>
  );
}

function ModeToggle({ mode, setMode, th }) {
  const opts = [
    { id: "paleo", label: "パレオ", sub: "標準モード", color: "#9E5518" },
    { id: "reboot", label: "リブート", sub: "30日の除去", color: C.greenDeep },
  ];
  return (
    <div style={{ background: C.cardWarm, borderRadius: 14, padding: 4, display: "flex", gap: 4, marginBottom: 14 }}>
      {opts.map((o) => {
        const on = mode === o.id;
        return (
          <button key={o.id} onClick={() => setMode(o.id)} style={{
            flex: 1, borderRadius: 11, border: "none", cursor: "pointer", fontFamily: FONT,
            background: on ? C.card : "transparent", padding: "9px 6px",
            boxShadow: on ? "0 1px 4px rgba(90,80,50,0.10)" : "none" }}>
            <div style={{ fontSize: 14.5, fontWeight: 800, color: on ? o.color : C.inkFaint }}>{o.label}</div>
            <div style={{ fontSize: 10.5, color: on ? C.inkSoft : C.inkFaint, marginTop: 1 }}>{o.sub}</div>
          </button>
        );
      })}
    </div>
  );
}

function nutritionWatch(state, today) {
  const out = [];
  const days = [];
  for (let i = 0; i < 7; i++) {
    const ds = todayStr(addDays(parseLocalDate(today), -i));
    if (state.days[ds]) days.push(state.days[ds]);
  }
  const flagCount = (f) => days.filter(d => {
    const all = [...d.meals.breakfast,...d.meals.lunch,...d.meals.dinner,...d.meals.snack];
    return all.some(it => (it.f||[]).includes(f));
  }).length;

  const fish = flagCount("fish");
  out.push(fish >= 3
    ? { ok: true, title: "オメガ3 / ビタミンD ◎", msg: `直近で魚を${fish}回。青魚を週3回の目標をキープできています。` }
    : { ok: false, title: "オメガ3 / ビタミンD 不足ぎみ", msg: `乳製品を抜くとビタミンD源が減ります。青魚(サバ・イワシ・鮭)を週3回以上に。今週はあと${Math.max(0,3-fish)}回。` });

  const veg = flagCount("veg");
  out.push({ ok: false, title: "カルシウム に注意", msg: "乳製品カットで不足しやすい栄養素です。小魚(丸ごと)・ホウレン草・ブロッコリー・わかめを意識して。" });

  out.push(veg >= 5
    ? { ok: true, title: "食物繊維 ◎", msg: "野菜がしっかり摂れています。腸内環境の維持に発酵食品も併せて。" }
    : { ok: false, title: "食物繊維 を増やしたい", msg: "穀類・豆類を抜くと繊維が減りがち。葉物・きのこ・海藻・サツマイモで補って。" });

  return out;
}

function CompletionCard({ state, start }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button onClick={() => setOpen(true)} style={{ width: "100%", marginTop: 12, background: C.greenDeep,
        color: "#fff", border: "none", borderRadius: 16, padding: "14px", fontSize: 15, fontWeight: 700,
        fontFamily: FONT, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
        <Award size={19} /> 30日の振り返りレポートを見る
      </button>
      {open && <CompletionReport state={state} start={start} onClose={() => setOpen(false)} />}
    </>
  );
}

function CompletionReport({ state, start, onClose }) {
  const days = [];
  for (let i = 0; i < 30; i++) {
    const ds = todayStr(addDays(parseLocalDate(start), i));
    days.push(state.days[ds]);
  }
  const logged = days.filter(Boolean);
  const scores = logged.map(d => scoreDay(d, "reboot").score); // 30日リブート完走レポートなのでリブート基準で採点
  const avg = scores.length ? Math.round(scores.reduce((a,b)=>a+b,0)/scores.length) : 0;
  const fishDays = logged.filter(d => [...d.meals.breakfast,...d.meals.lunch,...d.meals.dinner,...d.meals.snack].some(it=>(it.f||[]).includes("fish"))).length;
  const violations = logged.filter(d => d.violation).length;

  const reintro = [
    { food: "卵", note: "最も再導入しやすい。まず1個食べて2〜3日、消化・肌・関節の様子を見る" },
    { food: "乳製品", note: "ヨーグルト少量から。お腹の張り・肌の反応をチェック" },
    { food: "ナス科(トマト・じゃがいも等)", note: "関節痛・炎症が出やすい人は慎重に。1品ずつ" },
    { food: "豆類(味噌・醤油・大豆)", note: "和食に戻すなら発酵大豆(味噌)から。お腹の調子を確認" },
    { food: "穀類(米)", note: "白米→玄米の順。血糖の急上昇・眠気・むくみを観察" },
  ];

  return (
    <Modal onClose={onClose} title="30日リブート 振り返り">
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
        <Stat label="記録した日数" value={`${logged.length}/30`} />
        <Stat label="平均スコア" value={`${avg}点`} />
        <Stat label="魚を食べた日" value={`${fishDays}日`} />
        <Stat label="違反した日" value={`${violations}日`} color={violations ? C.radish : C.green} />
      </div>
      <div style={{ background: C.greenSoft, borderRadius: 14, padding: 14, fontSize: 13, color: C.greenDeep, lineHeight: 1.6, marginBottom: 18 }}>
        お疲れさまでした。ここからが本番です。除去した食品を<b>1つずつ・2〜3日おき</b>に戻し、体調の変化を観察すると、自分に合わない食品が見えてきます。
      </div>
      <SectionLabel>再導入フェーズの進め方</SectionLabel>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {reintro.map((r, i) => (
          <div key={i} style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "12px 14px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ width: 22, height: 22, borderRadius: 999, background: C.carrotSoft, color: C.carrot,
                display: "grid", placeItems: "center", fontSize: 12, fontWeight: 800 }}>{i+1}</span>
              <span style={{ fontWeight: 700, fontSize: 14 }}>{r.food}</span>
            </div>
            <div style={{ fontSize: 12.5, color: C.inkSoft, marginTop: 6, lineHeight: 1.5 }}>{r.note}</div>
          </div>
        ))}
      </div>
      <div style={{ fontSize: 11, color: C.inkFaint, marginTop: 14, lineHeight: 1.5 }}>
        ※これは自己管理用の目安です。持病がある・薬を服用中の場合は主治医に相談してください。
      </div>
    </Modal>
  );
}

const Stat = ({ label, value, color = C.greenDeep }) => (
  <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 14, padding: "12px 14px" }}>
    <div style={{ fontSize: 11.5, color: C.inkSoft }}>{label}</div>
    <div style={{ fontSize: 22, fontWeight: 800, color, marginTop: 2 }}>{value}</div>
  </div>
);

